import React, { useEffect, useState } from 'react';
import API from '../api/axios';

const BookRoom = () => {
  const [formData, setFormData] = useState({
    roomName: 'Lab 1 - CS Dept', date: '', startTime: '09:00', endTime: '11:00', purpose: ''
  });
  const [myBookings, setMyBookings] = useState([]);

  const fetchBookings = () => {
    API.get('/bookings/my')
      .then(res => setMyBookings(res.data))
      .catch(err => console.error(err));
  };

  useEffect(() => { fetchBookings(); }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await API.post('/bookings', formData);
      alert('Booking request submitted!');
      fetchBookings();
    } catch (err) {
      alert(err.response?.data?.message || 'Booking conflict or error.');
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 grid grid-cols-1 md:grid-cols-2 gap-8">
      <div className="bg-white p-6 rounded-xl shadow border">
        <h2 className="text-xl font-bold mb-4">Book Classroom / Lab</h2>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="text-sm font-semibold">Select Venue</label>
            <select
              className="w-full mt-1 p-2 border rounded"
              value={formData.roomName}
              onChange={(e) => setFormData({ ...formData, roomName: e.target.value })}
            >
              <option>Lab 1 - CS Dept</option>
              <option>Lab 2 - AI Dept</option>
              <option>Seminar Hall A</option>
              <option>Auditorium Main</option>
              <option>Classroom 102</option>
            </select>
          </div>
          <div>
            <label className="text-sm font-semibold">Date</label>
            <input
              type="date" required className="w-full mt-1 p-2 border rounded"
              value={formData.date}
              onChange={(e) => setFormData({ ...formData, date: e.target.value })}
            />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-sm font-semibold">Start Time</label>
              <input
                type="time" required className="w-full mt-1 p-2 border rounded"
                value={formData.startTime}
                onChange={(e) => setFormData({ ...formData, startTime: e.target.value })}
              />
            </div>
            <div>
              <label className="text-sm font-semibold">End Time</label>
              <input
                type="time" required className="w-full mt-1 p-2 border rounded"
                value={formData.endTime}
                onChange={(e) => setFormData({ ...formData, endTime: e.target.value })}
              />
            </div>
          </div>
          <div>
            <label className="text-sm font-semibold">Event / Class Purpose</label>
            <textarea
              required rows="3" className="w-full mt-1 p-2 border rounded" placeholder="Hackathon practice, workshop, extra class..."
              value={formData.purpose}
              onChange={(e) => setFormData({ ...formData, purpose: e.target.value })}
            />
          </div>
          <button type="submit" className="w-full bg-sky-600 text-white font-bold py-2 rounded hover:bg-sky-700">
            Submit Booking Request
          </button>
        </form>
      </div>

      <div className="bg-white p-6 rounded-xl shadow border">
        <h2 className="text-xl font-bold mb-4">My Room Booking Requests</h2>
        {myBookings.length === 0 ? (
          <p className="text-slate-500 text-sm">No booking requests submitted.</p>
        ) : (
          <div className="space-y-3">
            {myBookings.map((b) => (
              <div key={b._id} className="p-4 border rounded-lg flex justify-between items-center">
                <div>
                  <h4 className="font-bold text-slate-800">{b.roomName}</h4>
                  <p className="text-xs text-slate-500">📅 {b.date} | ⏰ {b.startTime} - {b.endTime}</p>
                  <p className="text-xs text-slate-600 mt-1">Purpose: {b.purpose}</p>
                </div>
                <span className={`px-3 py-1 rounded-full text-xs font-bold ${
                  b.status === 'Approved' ? 'bg-emerald-100 text-emerald-800' :
                  b.status === 'Rejected' ? 'bg-red-100 text-red-800' : 'bg-amber-100 text-amber-800'
                }`}>
                  {b.status}
                </span>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default BookRoom;
